import { Platform } from "@shared/index";
const CRONTAB_PATH = "/etc/crontab";
const CRON_TICK_MS = 15000;
// Matches a single cron field (`*`, `5`, `1,3,5`, `1-5`, `*/15`, ...) against
// a calendar value.
const fieldMatches = (field, value) => {
    return field.split(",").some((part) => {
        if (part === "*")
            return true;
        if (part.includes("/")) {
            const [range, step] = part.split("/");
            const start = range === "*" ? 0 : parseInt(range, 10);
            return value >= start && (value - start) % parseInt(step, 10) === 0;
        }
        if (part.includes("-")) {
            const [start, end] = part.split("-").map(Number);
            return value >= start && value <= end;
        }
        return parseInt(part, 10) === value;
    });
};
// Parses standard 5-field crontab lines (`m h dom mon dow command...`).
// Blank lines and lines starting with `#` are ignored.
export const parseCrontab = (content) => {
    return content
        .split("\n")
        .map((line) => line.trim())
        .filter((line) => line && !line.startsWith("#"))
        .map((line) => {
        const [minute, hour, dom, month, dow, ...command] = line.split(/\s+/);
        return { minute, hour, dom, month, dow, command: command.join(" ") };
    })
        .filter((job) => job.command);
};
const jobMatchesTime = (job, now) => fieldMatches(job.minute, now.getMinutes()) &&
    fieldMatches(job.hour, now.getHours()) &&
    fieldMatches(job.dom, now.getDate()) &&
    fieldMatches(job.month, now.getMonth() + 1) &&
    fieldMatches(job.dow, now.getDay());
// A job's command is either a path to a script or a `execCommand` DSL
// expression (e.g. `service('root', 'exec') ('/opt/cron/check-public-ip.js')`).
// `.js`/`.run` paths are run explicitly with `host.runFile` — the crontab is
// the user's own schedule, so no confirmation — because `host.exec` is "open"
// (decisions.md D10) and would show a script outside the system folders in
// the editor instead of running it. Other paths are opened as before.
const runJob = (job) => {
    const platform = Platform.getInstance();
    try {
        if (job.command.startsWith("/")) {
            const [filepath, ...args] = job.command.split(/\s+/);
            if (/\.(js|run)$/i.test(filepath)) {
                platform.host.runFile(platform, filepath, args, { confirm: false });
            }
            else {
                platform.host.exec(platform, filepath, ...args);
            }
        }
        else {
            platform.host.execCommand(job.command, platform);
        }
    }
    catch (err) {
        console.error(`cron: failed to run job "${job.command}"`, err);
    }
};
const minuteKey = (now) => `${now.getFullYear()}-${now.getMonth()}-${now.getDate()}-${now.getHours()}-${now.getMinutes()}`;
// Polls `/etc/crontab` and runs any due jobs, at most once per calendar
// minute. Returns the interval id so callers can stop it if needed.
export const startCronScheduler = () => {
    let lastMinuteKey = "";
    const tick = () => {
        const platform = Platform.getInstance();
        try {
            const fs = platform.host.getFS();
            if (!fs.existsSync(CRONTAB_PATH))
                return;
            const now = new Date();
            const key = minuteKey(now);
            if (key === lastMinuteKey)
                return;
            lastMinuteKey = key;
            const content = fs.readFileSync(CRONTAB_PATH, "utf-8");
            parseCrontab(content)
                .filter((job) => jobMatchesTime(job, now))
                .forEach(runJob);
        }
        catch (err) {
            console.error("cron: tick failed", err);
        }
    };
    tick();
    return window.setInterval(tick, CRON_TICK_MS);
};
